INSERT INTO `hotfixes`.`spell` (`ID`, `NameSubtext`, `Description`, `AuraDescription`, `VerifiedBuild`) VALUES
(1404001, '', 'Hurl a bolt of vengeful loa spite at the target, searing it with shadow.', 'Hurl a bolt of vengeful loa spite at the target, searing it with shadow.', 69933),
(1404002, '', 'Call on a friendly spirit to wrap an ally in healing mojo.', 'Call on a friendly spirit to wrap an ally in healing mojo.', 69933),
(1404003, '', 'Hex the target, turning it into a harmless frog for a short while.', 'Hex the target, turning it into a harmless frog for a short while.', 69933),
(1404004, '', 'Poison the target with a jungle venom dart that eats away at it over time.', 'Poison the target with a jungle venom dart that eats away at it over time.', 69933),
(1404005, '', 'Slip between worlds as a spirit, running faster and shrugging off roots.', 'Slip between worlds as a spirit, running faster and shrugging off roots.', 69933),
(1404006, '', 'Plant a ward carved with healing glyphs that mends nearby allies.', 'Plant a ward carved with healing glyphs that mends nearby allies.', 69933),
(1404007, '', 'Drain a piece of the target''s soul, harming it and healing you.', 'Drain a piece of the target''s soul, harming it and healing you.', 69933),
(1404008, '', 'Stick pins in a doll of the target, wracking it with growing agony.', 'Stick pins in a doll of the target, wracking it with growing agony.', 69933),
(1404009, '', 'Call up undead jungle hounds from the grave to tear at your enemies.', 'Call up undead jungle hounds from the grave to tear at your enemies.', 69933),
(1404010, '', 'Unleash a chain of crackling spirit lightning that leaps between enemies.', 'Unleash a chain of crackling spirit lightning that leaps between enemies.', 69933),
(1404011, '', 'The Loa of death shelters you, turning your pain into healing for a short time.', 'The Loa of death shelters you, turning your pain into healing for a short time.', 69933),
(1404012, '', 'Invoke the old rites. Spirits of the loa quicken you and your allies for a short time.', 'Invoke the old rites. Spirits of the loa quicken you and your allies for a short time.', 69933),
(1404020, '', 'The favor of the loa strengthens your craft, increasing all healing you deal by 5%.', 'The favor of the loa strengthens your craft, increasing all healing you deal by 5%.', 69933),
(1404021, '', 'Decades of voodoo sharpen your curses, increasing your Shadow and Nature damage by 5%.', 'Decades of voodoo sharpen your curses, increasing your Shadow and Nature damage by 5%.', 69933);
